package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import java.util.zip.GZIPInputStream;

import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.backup.BackupRequest;
import org.eclipse.rdf4j.sail.backup.BackupType;
import org.eclipse.rdf4j.sail.lmdb.LmdbBackupDeltaCodec.Record;
import org.eclipse.rdf4j.sail.lmdb.PostCommitBackupPublisher.Stage;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

@Timeout(30)
class LmdbBackupIdentityTest {

	private static final int PREPARATIONS = 513;

	@Test
	void abandonedPreparationsKeepFreshVersionFourIdentitiesAcrossRestart(@TempDir Path directory) throws Exception {
		Path live = directory.resolve("live");
		Path backups = directory.resolve("backups");
		Set<UUID> identities = new HashSet<>();
		List<Record> abandoned = List.of(new Record(true, true, statement("abandoned")));
		long baseline = -1;
		UUID committedHead = PostCommitBackupPublisher.EMPTY;
		for (int round = 0; round < 2; round++) {
			LmdbStore store = new LmdbStore(live.toFile(), new LmdbStoreConfig().setBackupJournalEnabled(true));
			store.init();
			try {
				LmdbBackupServiceImpl service = (LmdbBackupServiceImpl) store.getBackupService();
				if (round == 0) {
					baseline = service.createBackup(BackupRequest.builder(backups, BackupType.FULL).build())
							.getEndTransactionId();
				}
				TripleStore triples = store.getBackingStore().getTripleStore();
				long previous = store.getBackingStore().getCurrentCommittedTxnId();
				assertEquals(baseline + round, previous);
				assertEquals(committedHead, triples.getBackupOutboxHead());
				characterizeAbandonedPreparations(store, abandoned, identities);

				Statement committed = statement("kept-" + round);
				try (var connection = store.getConnection()) {
					connection.begin();
					connection.addStatement(committed.getSubject(), committed.getPredicate(), committed.getObject());
					connection.commit();
				}
				assertEquals(previous + 1, store.getBackingStore().getCurrentCommittedTxnId());
				Stage published;
				try (var input = new DataInputStream(new ByteArrayInputStream(
						triples.readBackupStageHeader(previous + 1)))) {
					published = PostCommitBackupPublisher.readStage(input, null);
				}
				assertEquals(committedHead, published.predecessor);
				assertEquals(previous, published.previousTransaction);
				assertEquals(previous + 1, published.transaction);
				assertEquals(1, published.count);
				assertFreshVersionFour(published.id, identities);
				committedHead = published.id;
				assertEquals(committedHead, triples.getBackupOutboxHead());

				service.createBackup(BackupRequest.builder(backups, BackupType.INCREMENTAL)
						.sinceTransactionId(baseline)
						.build());
				List<Path> logs = service.exportTransactionLogs(backups, previous, previous + 1,
						directory.resolve("exported-" + round));
				assertEquals(1, logs.size());
				ByteArrayOutputStream expected = new ByteArrayOutputStream();
				LmdbBackupDeltaCodec.write(expected, List.of(new Record(true, true, committed)), previous,
						store.getBackingStore().backupJournalState().generation());
				try (var input = new GZIPInputStream(Files.newInputStream(logs.getFirst()))) {
					assertArrayEquals(expected.toByteArray(), input.readAllBytes(),
							"Abandoned preparation state must not leak into a later real commit");
				}
			} finally {
				store.shutDown();
			}
		}
		assertEquals(2 * (PREPARATIONS + 1), identities.size());
	}

	private static void characterizeAbandonedPreparations(LmdbStore store, List<Record> records, Set<UUID> identities)
			throws Exception {
		LmdbSailStore backing = store.getBackingStore();
		TripleStore triples = backing.getTripleStore();
		PostCommitBackupPublisher publisher = backing.backupPublisher();
		long previous = backing.getCurrentCommittedTxnId();
		UUID predecessor = triples.getBackupOutboxHead();
		var acknowledgement = publisher.acknowledgement();
		List<Long> committedStages = triples.listBackupStageTransactions(0, Long.MAX_VALUE);
		// prepare sets tentative TripleStore fields. A real native transaction guarantees that existing
		// rollback cleanup clears them before any public commit, publisher close or store restart.
		try {
			triples.startTransaction();
			for (int preparation = 0; preparation < PREPARATIONS; preparation++) {
				Stage stage = publisher.prepare(previous, records);
				assertFreshVersionFour(stage.id, identities);
				assertEquals(predecessor, stage.predecessor);
				assertEquals(previous, stage.previousTransaction);
				assertEquals(previous + 1, stage.transaction);
				assertEquals(records.size(), stage.count);
			}
			assertEquals(previous, backing.getCurrentCommittedTxnId());
			assertEquals(predecessor, triples.getBackupOutboxHead());
			assertEquals(acknowledgement, publisher.acknowledgement());
		} finally {
			triples.rollback();
		}
		assertEquals(0L, triples.writeTxn);
		assertEquals(previous, backing.getCurrentCommittedTxnId());
		assertEquals(predecessor, triples.getBackupOutboxHead());
		assertEquals(acknowledgement, publisher.acknowledgement());
		assertEquals(committedStages, triples.listBackupStageTransactions(0, Long.MAX_VALUE));
	}

	private static void assertFreshVersionFour(UUID identity, Set<UUID> identities) {
		assertNotEquals(PostCommitBackupPublisher.EMPTY, identity);
		assertEquals(4, identity.version());
		assertEquals(2, identity.variant());
		assertTrue(identities.add(identity), "Each abandoned or committed preparation must have a fresh identity");
	}

	private static Statement statement(String label) {
		var values = SimpleValueFactory.getInstance();
		return values.createStatement(values.createIRI("urn:backup-identity:" + label),
				values.createIRI("urn:backup-identity:p"), values.createLiteral(label));
	}
}
